<script setup lang="ts">
import { computed } from "vue";
import { api } from "../../api/client";
import { useAppStore } from "../../stores/app";
import { useGraphStore } from "../../stores/graph";
import { useProjectStore } from "../../stores/project";
import type { LayerUpdate, LayoutUpdate, PortName, RelationUpdate, StyleUpdate, TextBoxUpdate } from "../../types";
const app = useAppStore(); const graph = useGraphStore(); const project = useProjectStore();
const item = computed(() => app.selection.length === 1 ? app.selection[0] : null);
const layer = computed(() => item.value?.kind === "layer" ? graph.rawGraph?.layers.find((row) => row.id === item.value!.id) : null);
const layout = computed(() => layer.value ? graph.rawGraph?.layouts.find((row) => row.layer_id === layer.value!.id) : null);
const style = computed(() => layer.value ? graph.rawGraph?.styles.find((row) => row.layer_id === layer.value!.id) : null);
const relation = computed(() => item.value?.kind === "relation" ? graph.rawGraph?.relations.find((row) => row.id === item.value!.id) : null);
const text = computed(() => item.value?.kind === "text" ? graph.rawGraph?.text_boxes.find((row) => row.id === item.value!.id) : null);
async function updateLayer(body: LayerUpdate) { if (layer.value) await graph.mutateGraph("Layer 저장", () => api.updateLayer(project.projectId, layer.value!.id, body)) }
async function updateLayout(body: LayoutUpdate) { if (layer.value) await graph.mutateGraph("배치 저장", () => api.updateLayout(project.projectId, layer.value!.id, body)) }
async function updateStyle(body: StyleUpdate) { if (layer.value) await graph.mutateGraph("스타일 저장", () => api.updateStyle(project.projectId, layer.value!.id, body)) }
async function updateRelation(body: RelationUpdate) { if (relation.value) await graph.mutateGraph("관계 저장", () => api.updateRelation(project.projectId, relation.value!.id, body)) }
async function updateText(body: TextBoxUpdate) { if (text.value) await graph.mutateGraph("텍스트 저장", () => api.updateText(project.projectId, text.value!.id, body)) }
function selectedPort(event: Event): PortName {
  const value = (event.target as HTMLSelectElement).value;
  return value === "top" || value === "right" || value === "bottom" || value === "left" ? value : "right";
}
</script>
<template><aside class="property-panel"><div class="side-heading"><span>PROPERTIES</span><button v-if="app.selection.length" @click="app.clearSelection()">×</button></div><div v-if="app.selection.length > 1" class="property-empty"><b>{{ app.selection.length }}개 선택</b><p>Toolbar에서 병합하거나 이동할 수 있습니다.</p></div><div v-else-if="layer" class="property-form"><div class="property-title"><span class="layer-dot"/><div><strong>{{ layer.name }}</strong><small>Layer</small></div></div><label>이름<input :value="layer.name" @change="updateLayer({ name: ($event.target as HTMLInputElement).value })"></label><label>Step<input :value="layer.step" @change="updateLayer({ step: ($event.target as HTMLInputElement).value || null })"></label><label>Property<input :value="layer.layer_property" @change="updateLayer({ layer_property: ($event.target as HTMLInputElement).value || null })"></label><label>Align<input :value="layer.align" @change="updateLayer({ align: ($event.target as HTMLInputElement).value || null })"></label><label>Align Side<input :value="layer.align_side" @change="updateLayer({ align_side: ($event.target as HTMLInputElement).value || null })"></label><label>Group<input :value="layer.pending_group" @change="graph.mutateGraph('그룹 저장', () => api.updateGroup(project.projectId, layer!.id, ($event.target as HTMLInputElement).value || null))"></label><div class="property-split"/><label v-if="layout">X<input type="number" :value="layout.x" @change="updateLayout({ x: Number(($event.target as HTMLInputElement).value) })"></label><label v-if="layout">Y<input type="number" :value="layout.y" @change="updateLayout({ y: Number(($event.target as HTMLInputElement).value) })"></label><label v-if="layout">Width<input type="number" :value="layout.width" @change="updateLayout({ width: Number(($event.target as HTMLInputElement).value) })"></label><label v-if="layout">Height<input type="number" :value="layout.height" @change="updateLayout({ height: Number(($event.target as HTMLInputElement).value) })"></label><div class="property-split"/><label v-if="style">Fill<input type="color" :value="style.fill_color" @change="updateStyle({ fill_color: ($event.target as HTMLInputElement).value })"></label><label v-if="style">Stroke<input type="color" :value="style.stroke_color" @change="updateStyle({ stroke_color: ($event.target as HTMLInputElement).value })"></label><label v-if="style">Text<input type="color" :value="style.text_color" @change="updateStyle({ text_color: ($event.target as HTMLInputElement).value })"></label></div><div v-else-if="relation" class="property-form"><div class="property-title"><span class="relation-dot"/><div><strong>Relation</strong><small>{{ relation.id.slice(0, 8) }}</small></div></div><label>Type<input :value="relation.relation_type" @change="updateRelation({ relation_type: ($event.target as HTMLInputElement).value })"></label><label>Instance<input :value="relation.instance" @change="updateRelation({ instance: ($event.target as HTMLInputElement).value || null })"></label><label>Source<select :value="relation.source_port" @change="updateRelation({ source_port: selectedPort($event) })"><option v-for="port in ['top','right','bottom','left']" :key="port">{{ port }}</option></select></label><label>Target<select :value="relation.target_port" @change="updateRelation({ target_port: selectedPort($event) })"><option v-for="port in ['top','right','bottom','left']" :key="port">{{ port }}</option></select></label><label>Arrow<select :value="relation.relation_style_id || ''" @change="updateRelation({ relation_style_id: ($event.target as HTMLSelectElement).value || null })"><option value="">기본</option><option v-for="row in graph.rawGraph?.relation_styles" :key="row.id" :value="row.id">{{ row.name }}</option></select></label><p class="meta-box">Waypoints {{ relation.waypoints.length }}개<br>Attached {{ relation.attached_relation_id ? relation.attached_relation_id.slice(0, 8) : '없음' }}</p></div><div v-else-if="text" class="property-form"><div class="property-title"><strong>Text Box</strong></div><label>텍스트<textarea :value="text.text" @change="updateText({ text: ($event.target as HTMLTextAreaElement).value })"/></label><label>Font Size<input type="number" :value="text.font_size" @change="updateText({ font_size: Number(($event.target as HTMLInputElement).value) })"></label><label>Text Color<input type="color" :value="text.text_color" @change="updateText({ text_color: ($event.target as HTMLInputElement).value })"></label><label>Locked<input type="checkbox" :checked="text.locked" @change="updateText({ locked: ($event.target as HTMLInputElement).checked })"></label></div><div v-else class="property-empty"><div class="empty-icon">◇</div><b>선택된 객체가 없습니다.</b><p>Canvas에서 Layer, 관계선 또는 Text Box를 선택하세요.</p></div></aside></template>
